mapper.update:
UPDATE tc_model_variableid
   SET description = #{m.description},
       updated_at = CURRENT_TIMESTAMP
 WHERE model_key = #{m.modelKey}
   AND variable_id_type = #{m.variableIdType, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
   AND variable_id = #{m.variableId}

mapper.select:
SELECT 
  FROM tc_model_variableid
 WHERE model_key = #{modelKey}
   AND variable_id_type = #{variableIdType, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
   AND variable_id = #{variableId}

SELECT 
  FROM tc_model_variableid
 WHERE model_key = #{modelKey}
 ORDER BY variable_key ASC

    LIMIT #{limit} OFFSET #{offset}
